"""Berggren tree expansion with Saunderson lifting to Euler bricks."""

from __future__ import annotations

from typing import Callable, Iterator, List, Tuple

Triple = Tuple[int, int, int]


def berg_A(t: Triple) -> Triple:
    a, b, c = t
    return (a - 2 * b + 2 * c, 2 * a - b + 2 * c, 2 * a - 2 * b + 3 * c)


def berg_B(t: Triple) -> Triple:
    a, b, c = t
    return (a + 2 * b + 2 * c, 2 * a + b + 2 * c, 2 * a + 2 * b + 3 * c)


def berg_C(t: Triple) -> Triple:
    a, b, c = t
    return (-a + 2 * b + 2 * c, -2 * a + b + 2 * c, -2 * a + 2 * b + 3 * c)


GENERATORS: Tuple[Callable[[Triple], Triple], ...] = (berg_A, berg_B, berg_C)
SEED: Triple = (3, 4, 5)


def saunderson(t: Triple) -> Triple:
    """Lift a Pythagorean triple to an Euler brick."""
    u, v, w = t
    return (u * (4 * v * v - w * w), v * (4 * u * u - w * w), 4 * u * v * w)


def face_diagonals(t: Triple) -> Triple:
    """Closed-form face diagonals of the lifted brick."""
    u, v, w = t
    return (abs(w) ** 3, abs(u) * (w * w + 4 * v * v), abs(v) * (w * w + 4 * u * u))


def levels(max_depth: int) -> Iterator[Tuple[int, List[Triple]]]:
    """Yield (depth, nodes) for depth = 0 .. max_depth; level n has 3**n nodes."""
    layer: List[Triple] = [SEED]
    for d in range(max_depth + 1):
        yield d, layer
        layer = [g(t) for t in layer for g in GENERATORS]


def expand_with_bricks(max_depth: int) -> List[Tuple[int, Triple, Triple, Triple]]:
    """Return (depth, node, brick, face diagonals) for every node up to max_depth."""
    out: List[Tuple[int, Triple, Triple, Triple]] = []
    for d, layer in levels(max_depth):
        for t in layer:
            out.append((d, t, saunderson(t), face_diagonals(t)))
    return out


if __name__ == "__main__":
    for d, node, brick, diag in expand_with_bricks(2)[:5]:
        print(d, node, tuple(abs(e) for e in brick), diag)

"""Decision procedure for the perfect-cuboid condition on the brick tree:
congruence screening followed by exact square trapping."""

from __future__ import annotations

from math import isqrt
from typing import Dict, List, Optional, Tuple

Triple = Tuple[int, int, int]

SMALL_MODULI: Tuple[int, ...] = (7, 8, 5, 13, 16, 3)


def squares_mod(m: int) -> frozenset:
    return frozenset((s * s) % m for s in range(m))


SQUARE_TABLES: Dict[int, frozenset] = {m: squares_mod(m) for m in SMALL_MODULI}


def quartic(t: Triple) -> int:
    """Q = c^4 + 16 a^2 b^2; the brick over (a,b,c) is perfect iff Q is square."""
    a, b, c = t
    return c**4 + 16 * a * a * b * b


def congruence_certificate(t: Triple) -> Optional[int]:
    """Return a modulus witnessing that Q is a nonresidue, or None."""
    Q = quartic(t)
    for m, table in SQUARE_TABLES.items():
        if Q % m not in table:
            return m
    return None


def square_trap(Q: int) -> Optional[Tuple[int, int]]:
    """Return (k, k+1) with k^2 < Q < (k+1)^2 if Q is not a square."""
    k = isqrt(Q)
    if k * k == Q:
        return None
    return (k, k + 1)


def decide_node(t: Triple) -> Dict[str, object]:
    """Full decision: congruence screen, then exact integer square root."""
    Q = quartic(t)
    m = congruence_certificate(t)
    trap = square_trap(Q)
    return {
        "node": t,
        "quartic": Q,
        "congruence_modulus": m,
        "perfect_cuboid": trap is None,
        "trapping_squares": trap,
    }


def sweep(max_depth: int) -> List[Dict[str, object]]:
    """Decide every node of the tree up to the given depth."""
    from itertools import product as _p  # noqa: F401

    def A(t: Triple) -> Triple:
        a, b, c = t
        return (a - 2 * b + 2 * c, 2 * a - b + 2 * c, 2 * a - 2 * b + 3 * c)

    def B(t: Triple) -> Triple:
        a, b, c = t
        return (a + 2 * b + 2 * c, 2 * a + b + 2 * c, 2 * a + 2 * b + 3 * c)

    def C(t: Triple) -> Triple:
        a, b, c = t
        return (-a + 2 * b + 2 * c, -2 * a + b + 2 * c, -2 * a + 2 * b + 3 * c)

    results: List[Dict[str, object]] = []
    layer: List[Triple] = [(3, 4, 5)]
    for _ in range(max_depth + 1):
        results.extend(decide_node(t) for t in layer)
        layer = [g(t) for t in layer for g in (A, B, C)]
    return results


if __name__ == "__main__":
    res = sweep(4)
    print(len(res), "nodes;", sum(r["perfect_cuboid"] for r in res), "perfect cuboids")
    screened = sum(1 for r in res if r["congruence_modulus"] is not None)
    print(f"{screened} of {len(res)} rejected by congruence alone")

"""Sharpness analysis: how far a congruence certificate reaches in the tree."""

from __future__ import annotations

from typing import Dict, List, Optional, Sequence, Tuple

State = Tuple[int, int, int]


def zA(s: State, m: int) -> State:
    a, b, c = s
    return ((a - 2 * b + 2 * c) % m, (2 * a - b + 2 * c) % m,
            (2 * a - 2 * b + 3 * c) % m)


def zB(s: State, m: int) -> State:
    a, b, c = s
    return ((a + 2 * b + 2 * c) % m, (2 * a + b + 2 * c) % m,
            (2 * a + 2 * b + 3 * c) % m)


def certified(s: State, m: int) -> bool:
    """True when c^4 + 16 a^2 b^2 is a nonresidue modulo m."""
    a, b, c = s
    squares = {(x * x) % m for x in range(m)}
    return (c**4 + 16 * a * a * b * b) % m not in squares


def escape_word(s: State, m: int, max_len: int = 3) -> Optional[str]:
    """Shortest word in A, B reaching an uncertified state (breadth first)."""
    frontier: List[Tuple[State, str]] = [(s, "")]
    for _ in range(max_len + 1):
        new: List[Tuple[State, str]] = []
        for st, w in frontier:
            if not certified(st, m):
                return w if w else "eps"
            new.append((zA(st, m), w + "A"))
            new.append((zB(st, m), w + "B"))
        frontier = new
    return None


def largest_closed_certified_set(m: int) -> List[State]:
    """The largest set of certified states closed under both A and B.

    Computed as the greatest fixed point: start from all certified states and
    repeatedly delete any state whose A- or B-image has left the set.  If the
    result is empty, no certified binary subtree exists for this modulus.
    """
    S = {(a, b, c) for a in range(m) for b in range(m) for c in range(m)
         if certified((a, b, c), m)}
    changed = True
    while changed:
        changed = False
        for s in list(S):
            if zA(s, m) not in S or zB(s, m) not in S:
                S.discard(s)
                changed = True
    return sorted(S)


def report(moduli: Sequence[int] = (5, 7, 8, 9, 11, 13, 16)) -> Dict[int, dict]:
    """For each modulus: certified fraction, worst escape length, closed set."""
    out: Dict[int, dict] = {}
    for m in moduli:
        states = [(a, b, c) for a in range(m) for b in range(m) for c in range(m)]
        cert = [s for s in states if certified(s, m)]
        words = [escape_word(s, m) for s in states]
        out[m] = {
            "certified_fraction": len(cert) / len(states),
            "states_without_escape": sum(1 for w in words if w is None),
            "max_escape_length": max((0 if w == "eps" else len(w))
                                     for w in words if w is not None),
            "largest_two_generator_closed_certified_set": len(
                largest_closed_certified_set(m)),
        }
    return out


if __name__ == "__main__":
    for m, data in report().items():
        print(m, data)
